import{_ as r,C as o,o as p,c as i,j as t,a as l,E as n,a5 as u}from"./chunks/framework.DNkHA0lr.js";const g=JSON.parse('{"title":"创作者们正在退出YouTube……为什么？","description":"","frontmatter":{"title":"创作者们正在退出YouTube……为什么？","originalTitle":"creators are quitting youtube… why?","date":"2024-07-20","originalUrl":"https://thedankoe.com/blog/creators-are-quitting-youtube-why/","minutes":3,"sourceHash":"add1b9dbff55f1b4ab137cd001987ce9a204d395835d38aec07666152f5b8b15","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/blog/creators-are-quitting-youtube-why/"}]]},"headers":[],"relativePath":"blog/creators-are-quitting-youtube-why.md","filePath":"blog/creators-are-quitting-youtube-why.md"}'),s={name:"blog/creators-are-quitting-youtube-why.md"};function c(b,e,d,h,_,f){const a=o("ArticleMeta");return p(),i("div",null,[e[0]||(e[0]=t("h1",{id:"创作者们正在退出youtube-为什么",tabindex:"-1"},[l("创作者们正在退出YouTube……为什么？ "),t("a",{class:"header-anchor",href:"#创作者们正在退出youtube-为什么","aria-label":'Permalink to "创作者们正在退出YouTube……为什么？"'},"​")],-1)),n(a),e[1]||(e[1]=u('<p>前几天，我的时间线上弹出了一个帖子。</p><p>写帖子的那家伙是个社交媒体经理。他很擅长做账号增长。</p><p>那么，请原谅我，因为我没有保存那篇帖子（而且我还花了30分钟试图找到它，这在Instagram上根本不可能），所以这些并不是他的原话。</p><p>但在帖子中，他提到他暗自希望自己的生意失败。</p><p>为什么？</p><p>因为他和他的客户都觉得被社交媒体困住了。</p><ul><li>他们觉得自己无法做真实的自己，不得不去维持一个虚假的在线人设。</li><li>他们把内容视为达到目的的手段，而不是目的本身。</li><li>他觉得如果他们的生意失败了，他们反而会过得更好，因为这样他们终于可以彻底登出社交媒体，回归自然了。</li></ul><p>我很喜欢这个帖子，它很有见地，写得也很好，但这里存在一个更深层次的问题，而且我已经琢磨这个想法有阵子了。</p><p>过去几个月里，有大量的YouTuber和各领域的创作者宣布退出，因为算法不再青睐他们了。</p><p>他们没有放下自我去<em>变得更好</em>，反而觉得社交媒体公司应该迎合他们的风格，好让他们能像打工人那样生存下去。</p><p>成为一名创作者（creator）的全部意义在于，做你想做的事，谈你想谈的话题，并玩一场无限游戏——不断接受更多挑战、提升自我以达成目标。</p><p>这就是你当初开始的初衷。</p><p>你的大脑爱上了成长、挑战和进步，因为这正是让生活变得有意义的所在。</p><p>但很快，这对你来说变得无聊且重复了。</p><p>我们都知道这有多危险。</p><p>解决办法不是抱着“住在树林里就能解决所有问题”的妄想而彻底退出，因为一旦新生活方式的新鲜感褪去，那同样也会变得无聊且重复。</p><p>就像刚刚坠机在荒岛上的人一样，起初会有一阵混乱，但随后人们确定了自己的角色，一切变得平静，接着不知从哪儿冒出来一个人决定制造一点混乱，好让事情再次变得有趣。</p><p>解决办法是重新调整方向。</p><p>社交媒体并不糟糕，你只是关注并取悦了错误的人。</p><p>你不必为了取悦算法而创作内容，你只是缺乏把<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">你的兴趣变得足够有趣</a>的技能，以至于无法维持你理想的生活方式。</p><p>你不必把内容看作是达到目的的手段；你可以把它看作是一个施展你创造力的机会，看作是你永无止境的毕生心血的载体。</p><ul><li>是的，你的收入可能会下降，直到你进行足够的实验并站稳脚跟。</li><li>是的，你将不得不忘掉你给自己编程植入的数字意识形态。</li><li>而且是的，绝对有办法实现增长，但你却将自己无力适应和转型归咎于算法，而不是去不断调整，直到找到你热爱之物与人们需求之物的交集。</li></ul><p>这不是针对你个人，因为有很多人在读这篇文章，但也许你更适合待在朝九晚五所谓的舒适与安稳中，或者住在树林里，直到你意识到那并不能解决你的问题。</p><p>在我眼里，社交媒体不仅仅是你手机上的一个应用。</p><ul><li>它是一扇传送门，通向一个充满了与你有相同深度兴趣的人的国度。</li><li>它是你大脑的新陈代谢，让你能够猎取绝妙的想法并与世界分享。（我的大部分帖子只是我想分享的笔记或想法）。</li><li>它是一个开放市场，在这里你可以<a href="https://mentalmonetization.com/" target="_blank" rel="noreferrer">打造一款改变生活的产品</a>，并将其分发给你吸引来的同频之人（从而获得一份有意义的收入）。</li></ul><p>进化不会倒退。</p><p>数字化的前进征程只会越来越快。</p><p>你可以找到属于自己的位置，或者你也可以退出，然后意识到你以前拥有的生活是多么美好。</p><hr><p><a href="/en/blog/creators-are-quitting-youtube-why">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',30))])}const y=r(s,[["render",c]]);export{g as __pageData,y as default};
